// Překlady rozhraní: klíčem je český text, hodnoty [en, de, es, fr].

import Foundation

@MainActor func tx(_ s: String) -> String {
    let l = L.lang
    if l == .cs { return s }
    guard let row = UITexts.table[s] else { return s }
    let i = l.idx
    return i < row.count ? row[i] : row[0]
}

@MainActor func petName(_ idx: Int, baby: Bool) -> String {
    if Supporter.unlocked, let custom = UserDefaults.standard.string(forKey: "name\(idx)"), !custom.trimmingCharacters(in: .whitespaces).isEmpty {
        return custom
    }
    let names: [Lang: [String]] = [.cs: ["Medák", "Drápek", "Mládě"], .en: ["Bodger", "Scratch", "Cub"], .de: ["Brummi", "Kralle", "Junges"],
                                   .es: ["Melón", "Garra", "Cría"], .fr: ["Miel", "Griffe", "Petit"]]
    let n = names[L.lang] ?? names[.en]!
    return baby ? n[2] : n[idx % 2]
}

